CREATE TABLE financial_books(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,organization_id TEXT NOT NULL,currency TEXT NOT NULL,opening_date TEXT NOT NULL,balances_json TEXT NOT NULL,reference TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 0,created_by TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(tenant_id,organization_id,currency),FOREIGN KEY(organization_id) REFERENCES organizations(id));
CREATE TABLE financial_operations(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,book_id TEXT NOT NULL,operation_date TEXT NOT NULL,kind TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),tax_minor INTEGER NOT NULL DEFAULT 0 CHECK(tax_minor>=0),due_date TEXT,tax_due_date TEXT,party TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,reference TEXT NOT NULL,target_id TEXT,cash_activity TEXT NOT NULL CHECK(cash_activity IN ('Operacional','Investimento','Financiamento')),actual_entry_id TEXT,cost_role TEXT NOT NULL DEFAULT 'OPEX',created_by TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(tenant_id,book_id,reference),FOREIGN KEY(book_id) REFERENCES financial_books(id));
CREATE TABLE financial_operation_voids(operation_id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,reason TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(operation_id) REFERENCES financial_operations(id));
CREATE INDEX financial_operations_book_date ON financial_operations(tenant_id,book_id,operation_date);
CREATE TRIGGER financial_operation_scope BEFORE INSERT ON financial_operations WHEN NOT EXISTS(SELECT 1 FROM financial_books WHERE id=NEW.book_id AND tenant_id=NEW.tenant_id) BEGIN SELECT RAISE(ABORT,'financial operation outside tenant'); END;
CREATE TRIGGER financial_operation_immutable BEFORE UPDATE ON financial_operations BEGIN SELECT RAISE(ABORT,'financial operation immutable'); END;
CREATE TRIGGER financial_operation_no_delete BEFORE DELETE ON financial_operations BEGIN SELECT RAISE(ABORT,'financial operation immutable'); END;
CREATE TRIGGER financial_void_immutable BEFORE UPDATE ON financial_operation_voids BEGIN SELECT RAISE(ABORT,'financial reversal immutable'); END;
CREATE TRIGGER financial_void_no_delete BEFORE DELETE ON financial_operation_voids BEGIN SELECT RAISE(ABORT,'financial reversal immutable'); END;

CREATE VIEW financial_obligation_sources AS
SELECT b.id||':AR' id,b.tenant_id,b.id book_id,'AR' kind,b.opening_date operation_date,NULL due_date,CAST(json_extract(b.balances_json,'$.AR') AS INTEGER) amount_minor FROM financial_books b WHERE json_extract(b.balances_json,'$.AR')>0
UNION ALL SELECT b.id||':AP',b.tenant_id,b.id,'AP',b.opening_date,NULL,CAST(json_extract(b.balances_json,'$.AP') AS INTEGER) FROM financial_books b WHERE json_extract(b.balances_json,'$.AP')>0
UNION ALL SELECT b.id||':TAX',b.tenant_id,b.id,'TAX',b.opening_date,NULL,CAST(json_extract(b.balances_json,'$.TAX_PAYABLE') AS INTEGER) FROM financial_books b WHERE json_extract(b.balances_json,'$.TAX_PAYABLE')>0
UNION ALL SELECT o.id,o.tenant_id,o.book_id,CASE WHEN o.kind='saleCredit' THEN 'AR' WHEN o.kind IN ('taxDue','withholding') THEN 'TAX' ELSE 'AP' END,o.operation_date,o.due_date,o.amount_minor+o.tax_minor FROM financial_operations o WHERE o.kind IN ('saleCredit','costCredit','assetCredit','inventoryCredit','taxDue','withholding') AND NOT EXISTS(SELECT 1 FROM financial_operation_voids v WHERE v.operation_id=o.id)
UNION ALL SELECT o.id||':tax',o.tenant_id,o.book_id,'TAX',o.operation_date,o.tax_due_date,o.tax_minor FROM financial_operations o WHERE o.kind IN ('saleCredit','saleCash') AND o.tax_minor>0 AND NOT EXISTS(SELECT 1 FROM financial_operation_voids v WHERE v.operation_id=o.id);
CREATE TRIGGER financial_settlement_guard BEFORE INSERT ON financial_operations WHEN NEW.kind IN ('settle','taxOffset','withholding','revenueReturnCredit','costReturnCredit') AND NOT EXISTS(SELECT 1 FROM financial_obligation_sources d WHERE d.id=NEW.target_id AND d.tenant_id=NEW.tenant_id AND d.book_id=NEW.book_id AND d.operation_date<=NEW.operation_date AND (NEW.kind<>'taxOffset' OR d.kind='TAX') AND (NEW.kind NOT IN ('withholding','costReturnCredit') OR d.kind='AP') AND (NEW.kind<>'revenueReturnCredit' OR d.kind='AR') AND NEW.amount_minor+COALESCE((SELECT SUM(p.amount_minor) FROM financial_operations p WHERE p.tenant_id=NEW.tenant_id AND p.book_id=NEW.book_id AND p.target_id=d.id AND p.kind IN ('settle','taxOffset','withholding','revenueReturnCredit','costReturnCredit') AND NOT EXISTS(SELECT 1 FROM financial_operation_voids v WHERE v.operation_id=p.id)),0)<=d.amount_minor) BEGIN SELECT RAISE(ABORT,'settlement exceeds outstanding balance'); END;
CREATE TRIGGER financial_operation_source_once BEFORE INSERT ON financial_operations WHEN NEW.actual_entry_id IS NOT NULL AND EXISTS(SELECT 1 FROM financial_operations o WHERE o.tenant_id=NEW.tenant_id AND o.actual_entry_id=NEW.actual_entry_id AND NOT EXISTS(SELECT 1 FROM financial_operation_voids v WHERE v.operation_id=o.id)) BEGIN SELECT RAISE(ABORT,'actual source already linked'); END;
CREATE TRIGGER financial_void_dependencies BEFORE INSERT ON financial_operation_voids WHEN EXISTS(SELECT 1 FROM financial_operations o WHERE o.tenant_id=NEW.tenant_id AND o.target_id IN (NEW.operation_id,NEW.operation_id||':tax') AND NOT EXISTS(SELECT 1 FROM financial_operation_voids v WHERE v.operation_id=o.id)) BEGIN SELECT RAISE(ABORT,'reverse settlements first'); END;
CREATE TRIGGER financial_book_opening_guard BEFORE UPDATE ON financial_books WHEN NEW.id<>OLD.id OR NEW.tenant_id<>OLD.tenant_id OR NEW.organization_id<>OLD.organization_id OR NEW.currency<>OLD.currency OR NEW.created_by<>OLD.created_by OR NEW.created_at<>OLD.created_at OR NEW.revision<>OLD.revision+1 OR EXISTS(SELECT 1 FROM financial_operations o WHERE o.book_id=OLD.id AND NOT EXISTS(SELECT 1 FROM financial_operation_voids v WHERE v.operation_id=o.id)) BEGIN SELECT RAISE(ABORT,'opening locked by active operations'); END;

CREATE TRIGGER financial_void_scope BEFORE INSERT ON financial_operation_voids WHEN NOT EXISTS(SELECT 1 FROM financial_operations WHERE id=NEW.operation_id AND tenant_id=NEW.tenant_id) BEGIN SELECT RAISE(ABORT,'financial void outside tenant'); END;
CREATE TRIGGER financial_linked_actual_update BEFORE UPDATE ON performance_entries WHEN (NEW.id<>OLD.id OR NEW.tenant_id<>OLD.tenant_id OR NEW.created_at<>OLD.created_at OR NEW.organization_id<>OLD.organization_id OR NEW.period<>OLD.period OR NEW.scenario<>OLD.scenario OR COALESCE(NEW.version_id,'')<>COALESCE(OLD.version_id,'') OR NEW.currency<>OLD.currency OR NEW.line_code<>OLD.line_code OR NEW.amount_minor<>OLD.amount_minor OR NEW.source<>OLD.source) AND EXISTS(SELECT 1 FROM financial_operations o WHERE o.tenant_id=OLD.tenant_id AND o.actual_entry_id=OLD.id AND NOT EXISTS(SELECT 1 FROM financial_operation_voids v WHERE v.operation_id=o.id)) BEGIN SELECT RAISE(ABORT,'linked financial source is immutable'); END;
CREATE TRIGGER financial_linked_actual_delete BEFORE DELETE ON performance_entries WHEN EXISTS(SELECT 1 FROM financial_operations o WHERE o.tenant_id=OLD.tenant_id AND o.actual_entry_id=OLD.id AND NOT EXISTS(SELECT 1 FROM financial_operation_voids v WHERE v.operation_id=o.id)) BEGIN SELECT RAISE(ABORT,'linked financial source is immutable'); END;
CREATE TRIGGER financial_linked_catalog_update BEFORE UPDATE ON financial_line_catalog WHEN (NEW.code<>OLD.code OR NEW.tenant_id<>OLD.tenant_id OR NEW.classification<>OLD.classification) AND EXISTS(SELECT 1 FROM performance_entries e JOIN financial_operations o ON o.actual_entry_id=e.id AND o.tenant_id=e.tenant_id WHERE e.tenant_id=OLD.tenant_id AND e.line_code=OLD.code AND NOT EXISTS(SELECT 1 FROM financial_operation_voids v WHERE v.operation_id=o.id)) BEGIN SELECT RAISE(ABORT,'linked financial source is immutable'); END;
CREATE TRIGGER financial_linked_catalog_delete BEFORE DELETE ON financial_line_catalog WHEN EXISTS(SELECT 1 FROM performance_entries e JOIN financial_operations o ON o.actual_entry_id=e.id AND o.tenant_id=e.tenant_id WHERE e.tenant_id=OLD.tenant_id AND e.line_code=OLD.code AND NOT EXISTS(SELECT 1 FROM financial_operation_voids v WHERE v.operation_id=o.id)) BEGIN SELECT RAISE(ABORT,'linked financial source is immutable'); END;
